public abstract class Character implements Attackable {
    private final String name;
    private final int maxHp;
    private int hp;
    private double defenseMultiplier;
    private boolean defending = false;

    public void setHp(int hp) {
        this.hp = Math.max(0, Math.min(maxHp, hp));
    }

    public void defend() {
        defending = true;
        defenseMultiplier = Math.max(defenseMultiplier, 1.5);
    }

    public abstract int attack(Character target);

    public int attack(Character target, String skillName) {
        int baseDamage = attack(target);
        if ("critical".equalsIgnoreCase(skillName)) {
            int bonusDamage = Math.max(2, baseDamage / 2);
            target.receiveDamage(bonusDamage);
            return baseDamage + bonusDamage;
        }
        return baseDamage;
    }
}

public ActionResult executeEnemyTurn(Player player, Enemy enemy) {
    int damage;

    if (enemy instanceof SkillUser skillUser &&
            enemy.getHp() <= enemy.getMaxHp() / 2) {

        damage = skillUser.useSkill(player);
        return new ActionResult(
                enemy.getName() + " uses special attack! -" + damage + " HP",
                damage
        );
    }

    damage = enemy.attack(player);
    return new ActionResult(
            enemy.getName() + " attacks! -" + damage + " HP",
            damage
    );
}
